WITH with_windows AS (SELECT id, carrier, shipped_date, status, FIRST_VALUE(carrier) IGNORE NULLS OVER (PARTITION BY order_id ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_carrier, LAST_VALUE(carrier, TRUE) OVER (PARTITION BY status ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_carrier FROM shipments), scored AS (SELECT id, status, last_known_carrier, LAST_VALUE(carrier) IGNORE NULLS OVER (PARTITION BY carrier ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_carrier_2 FROM with_windows), filtered AS (SELECT *, LOWER(status) AS status_lower FROM scored WHERE status IN ('IN_TRANSIT', 'LOST')), filtered_shipments AS (SELECT *, SUBSTRING(status, 1, 2) AS status_prefix FROM filtered WHERE status IN ('LOST', 'RETURNED', 'DELIVERED')), valid AS (SELECT id, status, last_known_carrier, last_known_carrier_2, status_lower, status_prefix, INITCAP(TRIM(status)) AS status_title FROM filtered_shipments WHERE status = 'RETURNED'), stats AS (SELECT status, SIZE(COLLECT_SET(status)) AS num_status, COUNT(*) FILTER (WHERE status = 'LOST') AS lost_rows, GROUPING(status) AS grouping_level FROM valid GROUP BY ROLLUP (status)) SELECT status, num_status, CASE WHEN status RLIKE '^(DELIVERED|RETURNED)$' THEN 'OTHER_ZONE' WHEN status RLIKE '^(IN_TRANSIT|LOST)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS status_zone FROM stats ORDER BY status_zone DESC, status DESC
